<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{api,type ApiResponse}from'@whaashop/shared';
interface Address{id?:number;receiverName:string;phone:string;province?:string;city?:string;district?:string;detail:string;isDefault:boolean}
const rows=ref<Address[]>([]),dialog=ref(false),error=ref(''),saving=ref(false),deletingId=ref<number>(),form=reactive<Address>({receiverName:'',phone:'',province:'',city:'',district:'',detail:'',isDefault:false}),route=useRoute(),router=useRouter();
async function load(){rows.value=(await api.get<ApiResponse<Address[]>>('/shop/addresses')).data.data}
function edit(address?:Address){Object.assign(form,address??{id:undefined,receiverName:'',phone:'',province:'',city:'',district:'',detail:'',isDefault:!rows.value.length});error.value='';dialog.value=true}
function close(){if(saving.value)return;dialog.value=false;error.value=''}
async function save(){error.value='';saving.value=true;try{const creating=!form.id;if(form.id)await api.put(`/shop/addresses/${form.id}`,form);else await api.post('/shop/addresses',form);dialog.value=false;await load();const back=String(route.query.return??'');if(creating&&back.startsWith('/'))router.replace(back)}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function defaultAddress(id:number){await api.patch(`/shop/addresses/${id}/default`);await load()}
async function remove(id:number){await api.delete(`/shop/addresses/${id}`);deletingId.value=undefined;await load()}
onMounted(async()=>{await load();if(route.query.new==='1')edit()})
</script>

<template><div class="address-page"><div class="container sub-page"><div class="page-heading"><div><span>ADDRESS BOOK</span><h1>收货地址</h1><p>管理你的常用收货信息</p></div><button class="btn" @click="edit()">＋ 新增地址</button></div><div v-if="rows.length" class="address-grid"><article v-for="address in rows" :key="address.id" :class="['address-card',{default:address.isDefault}]"><span v-if="address.isDefault" class="default-tag">默认地址</span><div class="address-user"><i>{{address.receiverName.slice(0,1)}}</i><div><b>{{address.receiverName}}</b><span>{{address.phone}}</span></div></div><p>{{[address.province,address.city,address.district,address.detail].filter(Boolean).join(' ')}}</p><footer><button v-if="!address.isDefault" @click="defaultAddress(address.id!)">设为默认</button><span v-else>✓ 当前默认</span><div v-if="deletingId!==address.id"><button @click="edit(address)">编辑</button><button class="danger" @click="deletingId=address.id">删除</button></div><div v-else class="delete-confirm"><small>确认删除？</small><button class="danger" @click="remove(address.id!)">确认</button><button @click="deletingId=undefined">取消</button></div></footer></article><button class="address-add" @click="edit()"><b>＋</b><span>添加新的收货地址</span></button></div><div v-else class="empty-state"><b>⌖</b><h3>还没有收货地址</h3><p>添加地址后，结算会更加快捷</p><button class="btn" @click="edit()">＋ 添加地址</button></div></div></div>

<Teleport to="body"><transition name="address-modal"><div v-if="dialog" class="address-mask" @click.self="close"><section class="address-dialog" role="dialog" aria-modal="true" :aria-label="form.id?'编辑收货地址':'新增收货地址'"><header><div><span>DELIVERY ADDRESS</span><h2>{{form.id?'编辑收货地址':'新增收货地址'}}</h2><p>请填写真实有效的收货信息</p></div><button aria-label="关闭" @click="close">×</button></header><form @submit.prevent="save"><div class="address-form"><label><span>收货人</span><input v-model.trim="form.receiverName" maxlength="50" required placeholder="请输入收货人姓名"></label><label><span>联系电话</span><input v-model.trim="form.phone" maxlength="20" required placeholder="请输入联系电话"></label><label><span>省份</span><input v-model.trim="form.province" placeholder="例如：广东省"></label><label><span>城市</span><input v-model.trim="form.city" placeholder="例如：深圳市"></label><label><span>区县</span><input v-model.trim="form.district" placeholder="例如：南山区"></label><label class="wide"><span>详细地址</span><textarea v-model.trim="form.detail" rows="3" maxlength="200" required placeholder="街道、门牌号、小区及楼栋信息"></textarea></label><label class="check wide"><input v-model="form.isDefault" type="checkbox"><i></i><span>设为默认收货地址</span></label></div><p v-if="error" class="form-error">{{error}}</p><footer><button type="button" @click="close">取消</button><button class="save-address" :disabled="saving">{{saving?'正在保存…':'保存地址'}}</button></footer></form></section></div></transition></Teleport></template>

<style scoped>
.address-page{min-height:calc(100vh - 140px);background:linear-gradient(180deg,#fff7ef,#fffaf6 300px)}.sub-page{padding:38px 0 75px}.page-heading{display:flex;align-items:end;justify-content:space-between;margin-bottom:25px}.page-heading span{color:#f97316;font-size:10px;letter-spacing:2px;font-weight:900}.page-heading h1{font-size:34px;margin:6px 0}.page-heading p{color:#967866;margin:0}.address-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.address-card,.address-add{min-height:210px;position:relative;padding:23px;border:1px solid #f1e2d7;border-radius:18px;background:#fff;box-shadow:0 9px 27px #9a34110b}.address-card.default{padding:22px;border:2px solid #fb923c}.default-tag{position:absolute;right:0;top:0;padding:6px 13px;border-radius:0 16px 0 12px;background:#f97316;color:#fff;font-size:11px}.address-user{display:flex;gap:12px;align-items:center}.address-user i{width:43px;height:43px;display:grid;place-items:center;border-radius:50%;background:#ffedd5;color:#c2410c;font-style:normal;font-weight:800}.address-user b,.address-user span{display:block}.address-user span{margin-top:4px;color:#967866;font-size:12px}.address-card>p{min-height:50px;line-height:1.7;color:#684c3b}.address-card>footer{display:flex;align-items:center;justify-content:space-between;padding-top:14px;border-top:1px solid #f3e7df}.address-card button{border:0;background:none;color:#c2410c;cursor:pointer}.address-card .danger{color:#dc2626}.delete-confirm{display:flex;align-items:center;gap:4px}.delete-confirm small{color:#dc2626}.delete-confirm button{padding:4px}.address-add{display:grid;place-content:center;justify-items:center;border-style:dashed;color:#c2410c;cursor:pointer}.address-add:hover{border-color:#f97316;background:#fff8f2}.address-add b{font-size:32px}.address-add span{margin-top:9px}.empty-state{min-height:390px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border:1px solid #f1e2d7;border-radius:20px;background:#fff}.empty-state>b{font-size:48px;color:#fdba74}.empty-state h3{margin:10px}.empty-state p{margin:0 0 20px;color:#967866}
.address-mask{position:fixed;inset:0;z-index:120;display:grid;place-items:center;padding:20px;background:#43140780;backdrop-filter:blur(5px)}.address-dialog{width:min(680px,100%);max-height:90vh;overflow:auto;border-radius:22px;background:#fff;box-shadow:0 28px 85px #43140755}.address-dialog>header{min-height:112px;display:flex;align-items:flex-start;justify-content:space-between;padding:24px 27px 20px;border-bottom:1px solid #f1e3d9;background:#fffaf6}.address-dialog>header>div{display:flex;flex-direction:column;align-items:flex-start}.address-dialog>header span{color:#f97316;font-size:9px;line-height:1.4;letter-spacing:2px;font-weight:900}.address-dialog>header h2{margin:7px 0 5px;font-size:25px;line-height:1.2}.address-dialog>header p{margin:0;color:#967866;font-size:11px;line-height:1.5}.address-dialog>header button{width:36px;height:36px;flex:none;border:0;border-radius:50%;background:#fff0e5;color:#c2410c;font-size:23px;cursor:pointer}.address-dialog form{padding:28px 27px 25px}.address-form{display:grid;grid-template-columns:repeat(6,1fr);column-gap:16px;row-gap:20px}.address-form label{grid-column:span 3;min-width:0}.address-form label:nth-child(3),.address-form label:nth-child(4),.address-form label:nth-child(5){grid-column:span 2}.address-form label>span{display:block;margin-bottom:8px;color:#624737;font-size:12px;line-height:1.4;font-weight:800}.address-form input,.address-form textarea{width:100%;padding:12px 13px;border:1px solid #ead8ca;border-radius:10px;background:#fffdfb;font:inherit;outline:none;transition:.2s}.address-form input{height:48px}.address-form textarea{min-height:90px;line-height:1.6;resize:vertical}.address-form input:focus,.address-form textarea:focus{border-color:#fb923c;box-shadow:0 0 0 3px #ffedd5}.address-form .wide{grid-column:1/-1}.address-form .check{display:flex;align-items:center;gap:8px;cursor:pointer}.address-form .check input{position:absolute;opacity:0}.address-form .check i{width:18px;height:18px;flex:none;display:grid;place-items:center;border:1px solid #d9c0af;border-radius:5px;background:#fff}.address-form .check input:checked+i{border-color:#f97316;background:#f97316}.address-form .check input:checked+i::after{content:'✓';color:#fff;font-size:11px}.address-form .check span{margin:0}.form-error{padding:10px 13px;border-radius:9px;background:#fef2f2;color:#dc2626}.address-dialog form>footer{display:flex;justify-content:flex-end;gap:10px;margin-top:24px;padding-top:19px;border-top:1px solid #f3e7df}.address-dialog form>footer button{padding:10px 21px;border:1px solid #ead8ca;border-radius:99px;background:#fff;color:#765744;cursor:pointer}.address-dialog form>footer .save-address{border-color:#f97316;background:#f97316;color:#fff;font-weight:800}.save-address:disabled{opacity:.5}.address-modal-enter-active,.address-modal-leave-active{transition:.2s}.address-modal-enter-from,.address-modal-leave-to{opacity:0}.address-modal-enter-from .address-dialog,.address-modal-leave-to .address-dialog{transform:translateY(12px) scale(.98)}
@media(max-width:700px){.address-grid,.address-form{grid-template-columns:1fr}.address-form label,.address-form label:nth-child(3),.address-form label:nth-child(4),.address-form label:nth-child(5),.address-form .wide{grid-column:auto}.page-heading{align-items:flex-start}.address-grid{gap:12px}.address-mask{padding:0}.address-dialog{width:100%;max-height:100vh;height:100%;border-radius:0}.address-dialog>header{min-height:108px}.address-dialog>header,.address-dialog form{padding-left:20px;padding-right:20px}}
